    layoutInlineClefSpaceBeforeNote,
    mx,
    repStartOffset,
    headerChangeW,
    noteArea,
    systemShortestDur,
    showClefChange,
    firstOrdinaryOffset,
    chainLeadingGapW,
    chainFullTail,
