    inlineClefSpaceBeforeNote,
    noteAccCols,
    noteSteps,
    noteArea,
    systemShortestDur,
    showClefChange,
    firstOrdinaryOffset,
    chainLeadingGapW,
    chainFullTail,
    chainTerminalShortTail
