    noteAreaStartX,
    contentRightX,
    systemShortestDur,
    leftBoundaryCenterGap,
    layoutFirstSpringW,
    firstNoteGapOptions,
    beamedSet,
    hasRepeatStartBoundary,
    previousIsRepeatEnd,
