    measure: measure2,
    mx,
    mi,
    noteIdx,
    chordMeasureQN,
    curTimeSig,
    curTimeSigStyle,
    showTimeSigChange,
    showKeySigChange,
    keySigChangeInfo,
    keySigChangeW,
    curClef,
    showClefChange,
    clefChangeAfterBarline,
    clefChangeX,
    clefChangeW,
    inlineClefChanges,
    measureClef,
    measureKeySet,
    stepForPitch,
    measureAcc,
    isRepeatEnd,
    repStartOffset,
    graceXOffsets: measureSpacingPlan.gracePlan.graceXOffsetByIndex,
    mw,
    noteArea,
    beatXs,
    beamGroups,
    beamedSet,
    noteXs,
    totalDur,
    noteSteps,
    graceBeamGroups,
    graceBeamedSet
