  for (const note of measure2) {
    if (note.isGrace || note.duration <= 0 || isStructuralMarkerNote(note))
      continue;
    const x = attackXs[eventIndex];
    if (x != null)
      beatToX.set(cumBeat, x);
    cumBeat += note.duration;
    eventIndex++;
  }
  return beatToX;
