// src/music-rendering/renderer/systemLayout/skylineDebugNodes.ts
function buildSkylineProfile(skyline, left, right, baselineY) {
  const profile = [];
  let cursor2 = left;
  for (const segment of skyline.segments()) {
    const segLeft = Math.max(left, segment.x1);
    const segRight = Math.min(right, segment.x2);
    if (segRight <= left || segLeft >= right || segLeft >= segRight)
      continue;
    if (segLeft > cursor2) {
      profile.push({ left: cursor2, right: segLeft, y: baselineY, obstacle: false });
    }
    profile.push({ left: segLeft, right: segRight, y: segment.y, obstacle: true });
    cursor2 = segRight;
  }
  if (cursor2 < right) {
    profile.push({ left: cursor2, right, y: baselineY, obstacle: false });
  }
  const merged = [];
  for (const segment of profile) {
    const prev = merged[merged.length - 1];
    if (prev && prev.right === segment.left && prev.y === segment.y && prev.obstacle === segment.obstacle) {
      prev.right = segment.right;
    } else {
      merged.push(segment);
    }
  }
  return merged;
}
function skylineProfilePath(profile) {
  const first = profile[0];
  if (!first)
    return "";
  const commands = [`M ${first.left} ${first.y}`];
  let currentY = first.y;
  for (const segment of profile) {
    if (segment.y !== currentY) {
      commands.push(`L ${segment.left} ${currentY}`);
      commands.push(`L ${segment.left} ${segment.y}`);
      currentY = segment.y;
    }
    commands.push(`L ${segment.right} ${segment.y}`);
  }
  return commands.join(" ");
}
function renderSkylineDebugNodes(input) {
  const { skyline, kind, keyPrefix, left, right, baselineY } = input;
  const profile = buildSkylineProfile(skyline, left, right, baselineY);
  const path = skylineProfilePath(profile);
  if (!path)
    return [];
  const filledPath = `${path} L ${right} ${baselineY} L ${left} ${baselineY} Z`;
  const color = kind === "above" ? "#ff00ff" : "#00ffff";
  const elementBase = kind === "above" ? "above-staff-skyline-debug" : "below-staff-skyline-debug";
  return [
    el("path", {
      d: filledPath,
      fill: color,
      opacity: 0.08,
      "data-lily-element": `${elementBase}-fill`
    }, undefined, `${keyPrefix}-${kind}-skyline-fill`),
    el("path", {
      d: path,
      fill: "none",
      stroke: color,
      strokeWidth: 1.2,
      strokeLinejoin: "miter",
      strokeLinecap: "square",
      opacity: 0.95,
      "data-lily-element": elementBase
    }, undefined, `${keyPrefix}-${kind}-skyline-profile`),
    el("line", {
      x1: left,
      x2: right,
      y1: baselineY,
      y2: baselineY,
      stroke: color,
      strokeWidth: 0.75,
      strokeDasharray: "4 3",
      opacity: 0.45,
      "data-lily-element": `${elementBase}-baseline`
    }, undefined, `${keyPrefix}-${kind}-skyline-baseline`)
  ];
}

